# -*- coding: utf-8 -*-
S = "полный обзор задач 9 класса (очередь G9–G11), проверено вычислением"
P = {}
def E(t, why, **kw): P[t] = dict(src=S, why=why, **kw)
E("G9_TB_21_404", r"$y=-\frac3x$: $x^{2}+\frac9{x^{2}}=9\Rightarrow x^{4}-9x^{2}+9=0$, $x^{2}=\frac{9\pm3\sqrt5}{2}>0$ (оба значения положительны), то есть $4$ значения $x$: $\pm\sqrt{\frac{9+3\sqrt5}{2}}\approx\pm2{,}80$ и $\pm\sqrt{\frac{9-3\sqrt5}{2}}\approx\pm1{,}07$; каждому соответствует одно $y$ — четыре общие точки. В ключе стояло «в двух точках»",
  k=r"Пересекаются в четырёх точках.",
  dnew={0: (r"Пересекаются в двух точках.", r"Ученик решил биквадратное уравнение $x^{4}-9x^{2}+9=0$, но учёл только один из двух положительных корней $t=x^{2}$ (или решил, что ветви гиперболы дают по одной точке); каждое из двух значений $t$ даёт по две точки $\pm x$."),
        1: (r"Не пересекаются.", r"Ученик решил, что радиус окружности $3$ меньше расстояния до гиперболы; но вершина гиперболы $xy=-3$ находится на расстоянии $\sqrt{6}\approx2{,}45<3$ от начала координат, поэтому окружность её пересекает."),
        2: (r"Пересекаются в одной точке.", r"Ученик решил, что окружность касается гиперболы; но дискриминант $D=81-36=45>0$ и оба корня $t=x^{2}$ положительны, поэтому общих точек четыре.")})
E("G9_TB_21_407_2", r"граф $\{y=x^{2}\}\cup\{y=-2\}$ задаётся уравнением $(y-x^{2})(y+2)=0$ (произведение равно нулю, когда обращается в нуль хотя бы один множитель); ключ $x^{2}+2=0$ не имеет решений (пустой график)",
  k=r"$(y-x^{2})(y+2)=0$",
  dnew={0: (r"$x^{2}+2=0$", r"Ученик приравнял $x^{2}=-2$, то есть искал точки пересечения параболы и прямой, а не задавал их объединение; уравнение $x^{2}+2=0$ решений не имеет."),
        1: (r"$(y-x^{2})+(y+2)=0$", r"Ученик записал сумму вместо произведения; сумма $y-x^{2}+y+2=0$ задаёт одну параболу $y=\frac{x^{2}-2}{2}$, а не объединение двух графиков."),
        2: (r"$y=x^{2}-2$", r"Ученик вычел $2$ из правой части параболы, пытаясь «совместить» обе линии в одном выражении; это уравнение задаёт только смещённую параболу.")})
E("G9_TB_21_409", r"$x+y=a+1$, $3x-y=a-1$: $x=\frac a2$, $y=\frac a2+1$; $x>0\Rightarrow a>0$, $y>0\Rightarrow a>-2$; вместе $a>0$. В ключе стояло $a>1$ (при $a=0{,}5$ получаем $x=0{,}25>0$, $y=1{,}25>0$)",
  k=r"$a > 0$",
  dnew={0: (r"$a > -2$", r"Ученик учёл только условие $y>0$ (из $\frac a2+1>0$ следует $a>-2$) и забыл условие $x>0$."),
        1: (r"$a < 0$", r"Ученик перепутал знак неравенства при решении $\frac a2>0$."),
        2: (r"$a > 1$", r"Ученик из условия $x>0$ получил $\frac a2>\frac12$ (перепутал $0$ и $\frac12$) и ответил $a>1$; но при $a=0{,}5$ решение $x=0{,}25$, $y=1{,}25$ уже положительно.")})
E("G9_TB_22_267_1", r"$\frac{\sin^{2}\alpha-1}{1-\cos^{2}\alpha}=-\frac{\cos^{2}\alpha}{\sin^{2}\alpha}=-\operatorname{ctg}^{2}\alpha$; при $\alpha=\frac\pi6$: $-\left(\sqrt3\right)^{2}=-3$ (прямая проверка: $\frac{\frac14-1}{1-\frac34}=\frac{-3/4}{1/4}=-3$). В ключе стояло $-1$, верный ответ $-3$ был среди дистракторов",
  k=r"$-3$",
  dnew={0: (r"$-1$", r"Ученик решил, что числитель $\sin^{2}\alpha-1$ и знаменатель $1-\cos^{2}\alpha$ отличаются только знаком, и получил $-1$; но $\sin^{2}\alpha-1=-\cos^{2}\alpha$, а $1-\cos^{2}\alpha=\sin^{2}\alpha$."),
        1: (r"$3$", r"Ученик верно получил $\operatorname{ctg}^{2}\alpha$ и вычислил его значение $3$, но потерял знак минус, записав $\sin^{2}\alpha-1=1-\sin^{2}\alpha$."),
        2: (r"$-\dfrac{1}{3}$", r"Ученик верно получил $-\operatorname{ctg}^{2}\alpha$, но подставил $\operatorname{tg}\frac\pi6=\frac1{\sqrt3}$ вместо $\operatorname{ctg}\frac\pi6=\sqrt3$.")})
